// ===== Scan ubuntu-latest — liste les workflows GitHub contenant runs-on: ubuntu-latest =====
// Utilise $env.GITHUB_PAT (PAT GitHub centralisé)

const GITHUB = 'https://api.github.com';
const HEADERS = {
  'Authorization': 'Bearer ' + $env.GITHUB_PAT,
  'Accept': 'application/vnd.github+json',
  'User-Agent': 'rennesdev-vps-ops/1.0'
};

async function apiGet(url) {
  const res = await $http.sendRequest({
    method: 'GET',
    url: url,
    headers: HEADERS
  });
  if (res.statusCode >= 400) {
    console.warn(url + ' → ' + res.statusCode);
    return null;
  }
  return res.body;
}

// 1. Récupérer tous les repos actifs (non fork, non archived)
const repos = await apiGet(GITHUB + '/user/repos?type=owner&per_page=100&sort=updated');
if (!repos) {
  return [{ error: 'Impossible de récupérer la liste des repos', findings: [] }];
}

const activeRepos = repos.filter(r => !r.fork && !r.archived);
console.log(activeRepos.length + ' repos actifs à analyser');

// 2. Pour chaque repo, vérifier s'il a des workflows
const results = [];
let reposWithWorkflows = 0;
let totalUbuntuLatest = 0;

for (const repo of activeRepos) {
  const tree = await apiGet(GITHUB + '/repos/' + repo.full_name + '/git/trees/HEAD?recursive=1');
  if (!tree || !tree.tree) continue;

  const workflowFiles = tree.tree.filter(f => 
    f.path.startsWith('.github/workflows/') && f.path.endsWith('.yml')
  );

  if (workflowFiles.length === 0) continue;
  reposWithWorkflows++;

  const repoTmp = { repo: repo.full_name, url: repo.html_url, workflows: [] };

  for (const wf of workflowFiles) {
    const content = await apiGet(GITHUB + '/repos/' + repo.full_name + '/contents/' + wf.path);
    if (!content || !content.content) continue;

    const decoded = atob(content.content);
    const lines = decoded.split('\n');
    const ubuntuLines = [];

    for (let i = 0; i < lines.length; i++) {
      if (lines[i].includes('runs-on: ubuntu-latest') || lines[i].includes('runs-on: ubuntu-latest')) {
        ubuntuLines.push({ line: i + 1, content: lines[i].trim() });
      }
    }

    if (ubuntuLines.length > 0) {
      repoTmp.workflows.push({ file: wf.path, ubuntuLines: ubuntuLines });
      totalUbuntuLatest += ubuntuLines.length;
    }
  }

  if (repoTmp.workflows.length > 0) {
    results.push(repoTmp);
  }
}

// 3. Compiler le rapport structuré
const summary = {
  reposScanned: activeRepos.length,
  reposWithWorkflows: reposWithWorkflows,
  reposWithUbuntuLatest: results.length,
  totalUbuntuLatestOccurrences: totalUbuntuLatest,
  details: results,
  generatedAt: new Date().toISOString()
};

console.log('Rapport: ' + JSON.stringify(summary, null, 2));
return [summary];

// ===== Formate le rapport pour Telegram =====
const scanData = $('Code — scanne les workflows GitHub').item.json;
const ollamaResponse = $json.response || '';

// Nettoyer la réponse Ollama (enlever les guillemets de début/fin si présents)
let analysis = ollamaResponse.trim();
if (analysis.startsWith('"') && analysis.endsWith('"')) {
  analysis = analysis.slice(1, -1);
}

// Construire le message Telegram
let msg = '🤖 Scan ubuntu-latest — Rapport quotidien\n';
msg += '📅 ' + new Date().toLocaleString('fr', { timeZone: 'Europe/Paris' }) + '\n\n';
msg += '📊 Repos scannés : ' + scanData.reposScanned + '\n';
msg += '🔧 Repos avec workflows : ' + scanData.reposWithWorkflows + '\n';
msg += '⚠️ Repos avec ubuntu-latest : ' + scanData.reposWithUbuntuLatest + '\n';
msg += '📌 Occurrences totales : ' + scanData.totalUbuntuLatestOccurrences + '\n\n';

if (scanData.details && scanData.details.length > 0) {
  msg += '📋 Détail par repo :\n';
  for (const d of scanData.details) {
    msg += '\n🔸 ' + d.repo + '\n';
    for (const w of d.workflows) {
      const files = w.file.split('/').pop();
      const lines = w.ubuntuLines.map(l => '  L' + l.line + ' : `' + l.content + '`').join('\n');
      msg += '  📄 ' + files + ' (' + w.ubuntuLines.length + ' occ.)\n' + lines + '\n';
    }
  }
  msg += '\n---\n';
}

if (analysis && analysis !== '') {
  msg += '🧠 Analyse LLM :\n' + analysis + '\n';
}

msg += '\n#scanUbuntuLatest';

return [{ text: msg }];
